/**
 * Minute AI — single source of truth for backend + dashboard URLs.
 *
 * Local dev uses the defaults below as-is.
 * The production zip is generated by `extension/build.sh`, which overwrites
 * API_BASE / DASHBOARD_URL with MINUTE_AI_API_URL / MINUTE_AI_SITE_URL.
 * Do NOT hardcode production URLs anywhere else (background.js, offscreen.js,
 * popup.js all read from MINUTE_AI_CONFIG with a localhost fallback).
 */

/* eslint-disable no-unused-vars */
const MINUTE_AI_CONFIG = {
  API_BASE: "http://localhost:8000",
  DASHBOARD_URL: "http://localhost:3000",
  // Dashboard origins the extension syncs auth with (popup tab-query + docs).
  DASHBOARD_HOSTS: ["http://localhost:3000/*", "http://127.0.0.1:3000/*"],
};
